import csv, json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
REG=ROOT/'registry'; SYN=ROOT/'synthesis'; DEC=ROOT/'decisions'
for d in (REG,SYN,DEC): d.mkdir(parents=True,exist_ok=True)

