fields=list(roles[0])
with (REG/'primitive_roles.csv').open('w',newline='',encoding='utf-8') as f:
 w=csv.DictWriter(f,fieldnames=fields); w.writeheader(); w.writerows(roles)
with (REG/'primitive_roles.jsonl').open('w',encoding='utf-8') as f:
 for r in roles: f.write(json.dumps(r,ensure_ascii=False)+'\n')
md=['# Canonical primitive-role registry','',
    'Authority: Foundations II controls the preferred meanings. Foundations I’s older operational labels are retained as historical realizations, not competing definitions.','']
for r in roles:
 md += [f"## {r['role_id']} — {r['canonical_name']}",'',r['canonical_meaning'],'',f"- **Behavioral:** {r['behavioral']}",f"- **Verification:** {r['verification']}",f"- **Structural-categorical:** {r['structural']}",f"- **Activation:** {r['activation']}",f"- **Non-collapse boundary:** {r['boundary']}",f"- **Source:** {r['source_paper']} `{r['source_path']}` lines {r['source_line']} (`{r['source_label']}`).",'']
(REG/'primitive_roles.md').write_text('\n'.join(md),encoding='utf-8')

